import React, { useState } from 'react';
import PasswordSuggestions from './PasswordSuggestions';
import'./Signup.css';

function Signup() {
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [password, setPassword] = useState("");

  const rules = {
    length: password.length >= 8 && password.length <= 16,
    upper: /[A-Z]/.test(password),
    lower: /[a-z]/.test(password),
    number: /[0-9]/.test(password),
    special: /[!@#$%^&*]/.test(password),
  };
  
  return (
    <div className="signupContainer">
      <form className="signupForm montserratFont">
        <h2>Sign Up</h2>
        <input autoCapitalize="none" autoCorrect="off" className="textField"  type="text" placeholder="User Name" />
        <input autoCapitalize="none" autoCorrect="off" className="textField" type="email" placeholder="Email" />
            <input className="textField" type="password" placeholder="Enter password"
            onFocus={() => setShowSuggestions(true)}
            onBlur={() => setShowSuggestions(false)}
            />

            {showSuggestions && (
            <div className="suggestionsWrapper">
                <PasswordSuggestions />
             </div>
            )}
  
        <button className="signupButton" type="submit">Sign Up</button>
      </form>
      <p className="SigninLink montserratFont"> 
        Already have an account? <a href="/signin">Sign In</a>
      </p>
    </div>
  );
}

export default Signup;
